/**
 * TeleVoIPs Stream Inspector - a lab-only Flow app that records everything
 * `sdk.streams` delivers, so the switchboard's use of the streams can be built
 * against real payloads instead of the reference alone.
 *
 * It opens every feed that takes no argument at startup (retained, so it
 * collects while the page is closed), and the page opens the per-extension,
 * per-queue and per-user feeds on demand. The app holds a grant for every
 * stream: register it on a lab platform only, never beside production.
 */
import type { FlowContext } from '@netsapiens/flow-sdk';
import { useEffect, useMemo, useRef } from 'react';
import { FlowContextProvider, useRemoteApp } from '@netsapiens/flow-sdk';

import { startCollectors } from './collector';
import InspectorPage from './InspectorPage';

declare const __MF_NAME__: string;
declare const __APP_ID__: string;
declare const __APP_ROUTE__: string;

export default function App(flowContext: FlowContext) {
  const { sdk } = useRemoteApp(flowContext, __MF_NAME__);
  const contextRef = useRef(flowContext);
  contextRef.current = flowContext;

  const Page = useMemo(
    () =>
      function StreamInspectorPage() {
        return (
          <FlowContextProvider context={contextRef.current}>
            <InspectorPage />
          </FlowContextProvider>
        );
      },
    [],
  );

  useEffect(() => {
    const stop = startCollectors(sdk);
    sdk
      .registerRoute({
        id: __APP_ID__,
        parentPath: '/apps',
        path: __APP_ROUTE__,
        label: 'Stream Inspector',
        icon: 'mdi:access-point',
        component: Page,
      })
      .catch((error) => console.error('[stream-inspector] Failed to register route:', error));
    return () => {
      sdk.unregisterRoute(__APP_ID__);
      stop();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sdk]);

  return null;
}
