/**
 * The inspector's page: stream status, event counts, the live log, markers,
 * REST snapshots and the JSON export.
 */
import type * as React from 'react';
import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react';
import type { StreamStatus, Subscription } from '@netsapiens/flow-sdk';
import { useFlowContext, useManagingDomain, VERSION } from '@netsapiens/flow-sdk';

import type { Entry, TargetKind } from './collector';
import {
  buildExport,
  clearLog,
  countEvents,
  getDropped,
  getEntries,
  getSdk,
  getStatuses,
  getVersion,
  openTarget,
  record,
  RETAINED_STREAMS,
  snapshotRest,
  subscribe,
  TARGET_KINDS,
} from './collector';

declare const __APP_VERSION__: string;

const SHOWN = 300;
/** Auto snapshots: at most one per this many ms, and only after an event. */
const AUTO_GAP = 5000;

function useLog() {
  useSyncExternalStore(subscribe, getVersion);
  return { entries: getEntries(), statuses: getStatuses(), dropped: getDropped() };
}

function palette(theme: 'light' | 'dark') {
  return theme === 'dark'
    ? { bg: '#121212', panel: '#1e1e1e', line: '#333', text: '#e6e6e6', dim: '#9a9a9a', ok: '#4caf50', warn: '#ffb74d', bad: '#ef5350', accent: '#64b5f6' }
    : { bg: '#ffffff', panel: '#f6f7f9', line: '#dde1e6', text: '#1d1f23', dim: '#5f6670', ok: '#2e7d32', warn: '#b26a00', bad: '#c62828', accent: '#1565c0' };
}

function stateColor(s: StreamStatus | undefined, c: ReturnType<typeof palette>): string {
  switch (s?.state) {
    case 'live':
      return c.ok;
    case 'refused':
      return c.bad;
    case 'unavailable':
    case 'unconfirmed':
      return c.warn;
    default:
      return c.dim;
  }
}

function describe(s: StreamStatus | undefined): string {
  if (!s) return 'not opened';
  switch (s.state) {
    case 'live':
      return s.snapshot ? 'live (snapshot)' : 'live';
    case 'refused':
      return `refused: ${s.reason}`;
    case 'unavailable':
      return s.retrying ? 'unavailable, retrying' : 'unavailable';
    default:
      return s.state;
  }
}

const time = (t: number) => new Date(t).toLocaleTimeString(undefined, { hour12: false }) + '.' + String(t % 1000).padStart(3, '0');

export default function InspectorPage() {
  const { api, user, theme } = useFlowContext();
  const { managing } = useManagingDomain();
  const domain = managing || user.domain;
  const c = palette(theme);
  const { entries, statuses, dropped } = useLog();

  const [filter, setFilter] = useState('');
  const [kinds, setKinds] = useState<Record<string, boolean>>({ event: true, status: true, rest: true, mark: true });
  const [mark, setMark] = useState('');
  const [auto, setAuto] = useState(false);
  const [targetKind, setTargetKind] = useState<TargetKind>('queues.onQueue');
  const [targetArg, setTargetArg] = useState('');
  const [targets, setTargets] = useState<Array<{ name: string; sub: Subscription }>>([]);

  // Targeted feeds belong to the page: close them when it unmounts.
  const targetsRef = useRef(targets);
  targetsRef.current = targets;
  useEffect(() => () => targetsRef.current.forEach((t) => t.sub.unsubscribe()), []);

  // Auto snapshot: after a calls or queues event, read the REST view too.
  const lastAuto = useRef(0);
  const lastSeq = useRef(0);
  useEffect(() => {
    if (!auto) return;
    const fresh = entries.filter((e) => e.seq > lastSeq.current);
    if (fresh.length) lastSeq.current = fresh[fresh.length - 1].seq;
    const relevant = fresh.some((e) => e.kind === 'event' && /^(calls|queues)\./.test(e.stream));
    if (!relevant || Date.now() - lastAuto.current < AUTO_GAP) return;
    lastAuto.current = Date.now();
    void snapshotRest(api, domain);
  }, [api, auto, domain, entries]);

  const counts = useMemo(() => countEvents(entries), [entries]);
  const streamNames = useMemo(() => {
    const s = new Set<string>([...RETAINED_STREAMS, ...statuses.keys()]);
    return Array.from(s);
  }, [statuses]);

  const shown = useMemo(() => {
    const f = filter.trim().toLowerCase();
    const out: Entry[] = [];
    for (let i = entries.length - 1; i >= 0 && out.length < SHOWN; i--) {
      const e = entries[i];
      if (!kinds[e.kind]) continue;
      if (f && !`${e.stream} ${e.event}`.toLowerCase().includes(f) && !JSON.stringify(e.payload).toLowerCase().includes(f)) continue;
      out.push(e);
    }
    return out;
  }, [entries, filter, kinds]);

  const addMark = useCallback(() => {
    const text = mark.trim();
    if (!text) return;
    record('mark', 'mark', text, null);
    setMark('');
  }, [mark]);

  const openOne = useCallback(() => {
    const arg = targetArg.trim();
    if (!arg) return;
    const t = openTarget(targetKind, arg);
    if (t) setTargets((prev) => [...prev.filter((p) => p.name !== t.name), t]);
  }, [targetArg, targetKind]);

  const download = useCallback(() => {
    const json = buildExport({
      app: 'televoips-stream-inspector',
      appVersion: __APP_VERSION__,
      sdkVersion: VERSION,
      domain,
      managing: managing ?? null,
      userDomain: user.domain,
      userScope: user.scope ?? null,
      targets: targets.map((t) => t.name),
    });
    const url = URL.createObjectURL(new Blob([json], { type: 'application/json' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `stream-capture-${domain}-${new Date().toISOString().replace(/[:.]/g, '-')}.json`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }, [domain, managing, targets, user.domain, user.scope]);

  const notify = useCallback(() => {
    const id = `inspector-${Date.now()}`;
    getSdk()?.sendNotification({ id, title: 'Stream Inspector test', body: `Sent at ${new Date().toLocaleTimeString()}`, severity: 'info' });
    record('mark', 'mark', `sendNotification ${id}`, null);
  }, []);

  const box: React.CSSProperties = { background: c.panel, border: `1px solid ${c.line}`, padding: 12, marginBottom: 12 };
  const btn: React.CSSProperties = { padding: '4px 10px', border: `1px solid ${c.line}`, background: c.bg, color: c.text, cursor: 'pointer', font: 'inherit' };
  const input: React.CSSProperties = { padding: '4px 8px', border: `1px solid ${c.line}`, background: c.bg, color: c.text, font: 'inherit' };
  const th: React.CSSProperties = { textAlign: 'left', padding: '2px 8px', color: c.dim, fontWeight: 600 };
  const td: React.CSSProperties = { padding: '2px 8px', borderTop: `1px solid ${c.line}`, verticalAlign: 'top' };

  return (
    <div style={{ background: c.bg, color: c.text, padding: 16, font: '13px/1.45 system-ui, sans-serif', minHeight: '100%' }}>
      <h2 style={{ margin: '0 0 4px', fontSize: 20 }}>Stream Inspector</h2>
      <div style={{ color: c.dim, marginBottom: 12 }}>
        Domain <b style={{ color: c.text }}>{domain}</b> as {user.scope ?? 'unknown scope'} · SDK {VERSION} · app {__APP_VERSION__} ·{' '}
        {entries.length} entries{dropped ? ` (${dropped} oldest dropped)` : ''}. Collecting since the app loaded, page open or not. Lab use only:
        captures hold caller names and numbers.
      </div>

      <div style={box}>
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }}>
          <input
            style={{ ...input, flex: '1 1 280px' }}
            placeholder="Marker, e.g. 'external call into queue 6000, answered by 101'"
            value={mark}
            onChange={(e) => setMark(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && addMark()}
          />
          <button style={btn} onClick={addMark}>
            Add marker
          </button>
          <button style={btn} onClick={() => void snapshotRest(api, domain)}>
            REST snapshot
          </button>
          <label style={{ display: 'flex', gap: 4, alignItems: 'center' }}>
            <input type="checkbox" checked={auto} onChange={(e) => setAuto(e.target.checked)} />
            Auto snapshot after call/queue events (max 1 per {AUTO_GAP / 1000} s, 3 requests each)
          </label>
          <button style={btn} onClick={notify}>
            Send test notification
          </button>
          <button style={{ ...btn, borderColor: c.accent, color: c.accent, fontWeight: 600 }} onClick={download}>
            Download JSON
          </button>
          <button style={btn} onClick={() => window.confirm('Clear the log?') && clearLog()}>
            Clear
          </button>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(360px, 1fr))', gap: 12 }}>
        <div style={box}>
          <b>Streams</b>
          <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: 6 }}>
            <tbody>
              {streamNames.map((n) => {
                const s = statuses.get(n);
                const t = targets.find((x) => x.name === n);
                return (
                  <tr key={n}>
                    <td style={{ ...td, fontFamily: 'ui-monospace, monospace' }}>{n}</td>
                    <td style={{ ...td, color: stateColor(s, c), whiteSpace: 'nowrap' }}>{describe(s)}</td>
                    <td style={{ ...td, color: c.dim }}>
                      {s?.state === 'refused' ? s.message : null}
                      {t ? (
                        <button
                          style={{ ...btn, padding: '0 6px' }}
                          onClick={() => {
                            t.sub.unsubscribe();
                            setTargets((prev) => prev.filter((p) => p !== t));
                            record('mark', 'inspector', `closed ${n}`, null);
                          }}
                        >
                          close
                        </button>
                      ) : null}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          <div style={{ display: 'flex', gap: 6, marginTop: 8, flexWrap: 'wrap' }}>
            <select style={input} value={targetKind} onChange={(e) => setTargetKind(e.target.value as TargetKind)}>
              {TARGET_KINDS.map((k) => (
                <option key={k.kind} value={k.kind}>
                  {k.kind}
                </option>
              ))}
            </select>
            <input
              style={{ ...input, flex: 1 }}
              placeholder={TARGET_KINDS.find((k) => k.kind === targetKind)?.hint}
              value={targetArg}
              onChange={(e) => setTargetArg(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && openOne()}
            />
            <button style={btn} onClick={openOne}>
              Open
            </button>
          </div>
        </div>

        <div style={box}>
          <b>Event counts</b>
          <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: 6 }}>
            <thead>
              <tr>
                <th style={th}>Stream</th>
                <th style={th}>Event</th>
                <th style={th}>Count</th>
                <th style={th}>Last</th>
              </tr>
            </thead>
            <tbody>
              {counts.length ? (
                counts.map((k) => (
                  <tr key={`${k.stream} ${k.event}`} style={{ cursor: 'pointer' }} onClick={() => setFilter(`${k.stream} ${k.event}`)}>
                    <td style={{ ...td, fontFamily: 'ui-monospace, monospace' }}>{k.stream}</td>
                    <td style={td}>{k.event}</td>
                    <td style={td}>{k.n}</td>
                    <td style={{ ...td, color: c.dim }}>{time(k.last)}</td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td style={{ ...td, color: c.dim }} colSpan={4}>
                    No events yet. Make a call, change presence, or log an agent in.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <div style={box}>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap', marginBottom: 6 }}>
          <b>Log</b>
          <input style={{ ...input, flex: '1 1 240px' }} placeholder="Filter by stream, event or payload text" value={filter} onChange={(e) => setFilter(e.target.value)} />
          {(['event', 'status', 'rest', 'mark'] as const).map((k) => (
            <label key={k} style={{ display: 'flex', gap: 3, alignItems: 'center' }}>
              <input type="checkbox" checked={kinds[k]} onChange={(e) => setKinds((p) => ({ ...p, [k]: e.target.checked }))} />
              {k}
            </label>
          ))}
          <span style={{ color: c.dim }}>newest first, up to {SHOWN}</span>
        </div>
        {shown.map((e) => (
          <details key={e.seq} style={{ borderTop: `1px solid ${c.line}`, padding: '2px 0' }}>
            <summary style={{ cursor: 'pointer', fontFamily: 'ui-monospace, monospace', fontSize: 12 }}>
              <span style={{ color: c.dim }}>{time(e.t)}</span>{' '}
              <span style={{ color: e.kind === 'mark' ? c.warn : e.kind === 'rest' ? c.accent : e.kind === 'status' ? c.dim : c.text }}>
                {e.kind === 'mark' ? `* ${e.event}` : `${e.stream} ${e.event}`}
              </span>{' '}
              <span style={{ color: c.dim }}>{e.kind === 'event' ? summarize(e.payload) : ''}</span>
            </summary>
            <pre style={{ margin: '4px 0 6px 16px', fontSize: 12, whiteSpace: 'pre-wrap', wordBreak: 'break-all' }}>
              {JSON.stringify(e.payload, null, 2)}
            </pre>
          </details>
        ))}
      </div>
    </div>
  );
}

/** One line for the log row: the fields that identify the record. */
function summarize(p: unknown): string {
  if (!p || typeof p !== 'object') return '';
  const o = p as Record<string, unknown>;
  const party = (v: unknown) => {
    if (!v || typeof v !== 'object') return '';
    const x = v as Record<string, unknown>;
    return String(x.user ?? x.number ?? x.name ?? '');
  };
  const bits: string[] = [];
  for (const k of ['callId', 'recordId', 'queue', 'agent', 'user', 'device', 'state', 'status', 'presence', 'waiting']) {
    if (o[k] !== undefined && o[k] !== null && o[k] !== '') bits.push(`${k}=${String(o[k])}`);
  }
  if (o.from || o.to) bits.push(`${party(o.from)} -> ${party(o.to)}`);
  if (o.remote) bits.push(`remote=${party(o.remote)}`);
  if (o.through && typeof o.through === 'object') bits.push(`through=${party(o.through)}`);
  return bits.join('  ');
}
