/**
 * The inspector's log. Module-level so it keeps collecting for the whole
 * session, whether or not the page is open: every domain-wide feed is opened
 * with `sdk.streams.retain` at startup, and retain's handlers see every
 * delivery.
 *
 * Every stream method is written out literally. The platform derives an app's
 * grants by finding `.<subject>.<method>(` in its source, so a method picked at
 * runtime would be refused as not-granted.
 */
import type { FlowApiClient, RemoteAppSDK, StreamClient, StreamStatus, Subscription } from '@netsapiens/flow-sdk';

export type EntryKind = 'event' | 'status' | 'rest' | 'mark';

export interface Entry {
  seq: number;
  /** ISO time, for the export. */
  at: string;
  /** Epoch ms, for sorting and gaps. */
  t: number;
  kind: EntryKind;
  /** e.g. `calls.onDomainCalls`, or `rest` / `mark`. */
  stream: string;
  /** Handler name (`updated`, `stats`), status state, REST path or the mark text. */
  event: string;
  payload: unknown;
}

const MAX_ENTRIES = 20000;

let entries: Entry[] = [];
let seq = 0;
let dropped = 0;
const statuses = new Map<string, StreamStatus>();
const listeners = new Set<() => void>();
let version = 0;
let flushTimer: ReturnType<typeof setTimeout> | null = null;

function changed(): void {
  version += 1;
  if (flushTimer) return;
  // Batch UI updates: a busy domain delivers many events a second.
  flushTimer = setTimeout(() => {
    flushTimer = null;
    for (const l of listeners) l();
  }, 250);
}

export function record(kind: EntryKind, stream: string, event: string, payload: unknown): void {
  const t = Date.now();
  entries.push({ seq: ++seq, at: new Date(t).toISOString(), t, kind, stream, event, payload });
  if (entries.length > MAX_ENTRIES) {
    const cut = entries.length - MAX_ENTRIES;
    entries = entries.slice(cut);
    dropped += cut;
  }
  changed();
}

function setStatus(stream: string, s: StreamStatus): void {
  statuses.set(stream, s);
  record('status', stream, s.state, s);
}

export function subscribe(fn: () => void): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}
export const getVersion = (): number => version;
export const getEntries = (): readonly Entry[] => entries;
export const getStatuses = (): ReadonlyMap<string, StreamStatus> => statuses;
export const getDropped = (): number => dropped;

export function clearLog(): void {
  entries = [];
  dropped = 0;
  changed();
}

// --- runtime ---------------------------------------------------------------------

let sdk: RemoteAppSDK | null = null;

export function getSdk(): RemoteAppSDK | null {
  return sdk;
}

/** What a stream method's last argument needs: status into the log. */
const watch = (stream: string) => ({ onStatus: (s: StreamStatus) => setStatus(stream, s) });
/** A handler that logs its payload. */
const tap =
  (stream: string, event: string) =>
  (payload: unknown): void =>
    record('event', stream, event, payload);

type Retained = { key: string; stream: string; open: (s: StreamClient) => Subscription };

/** Every feed that takes no argument, opened for the session. */
const RETAINED: Retained[] = [
  {
    key: 'calls.onDomainCalls',
    stream: 'calls.onDomainCalls',
    open: (s) =>
      s.calls.onDomainCalls(
        { updated: tap('calls.onDomainCalls', 'updated'), ended: tap('calls.onDomainCalls', 'ended') },
        watch('calls.onDomainCalls'),
      ),
  },
  {
    key: 'queues.onDomainQueues',
    stream: 'queues.onDomainQueues',
    open: (s) =>
      s.queues.onDomainQueues(
        {
          stats: tap('queues.onDomainQueues', 'stats'),
          callUpdated: tap('queues.onDomainQueues', 'callUpdated'),
          callEnded: tap('queues.onDomainQueues', 'callEnded'),
          agentUpdated: tap('queues.onDomainQueues', 'agentUpdated'),
          agentAdded: tap('queues.onDomainQueues', 'agentAdded'),
          agentRemoved: tap('queues.onDomainQueues', 'agentRemoved'),
        },
        watch('queues.onDomainQueues'),
      ),
  },
  {
    key: 'presence.onDomain',
    stream: 'presence.onDomain',
    open: (s) => s.presence.onDomain(tap('presence.onDomain', 'change'), watch('presence.onDomain')),
  },
  {
    key: 'contacts.onDomain',
    stream: 'contacts.onDomain',
    open: (s) => s.contacts.onDomain(tap('contacts.onDomain', 'contact'), watch('contacts.onDomain')),
  },
  {
    key: 'subscribers.onDomain',
    stream: 'subscribers.onDomain',
    open: (s) => s.subscribers.onDomain(tap('subscribers.onDomain', 'update'), watch('subscribers.onDomain')),
  },
  {
    key: 'devices.onDomain',
    stream: 'devices.onDomain',
    open: (s) => s.devices.onDomain(tap('devices.onDomain', 'device'), watch('devices.onDomain')),
  },
  {
    key: 'cdrs.onDomain',
    stream: 'cdrs.onDomain',
    open: (s) =>
      s.cdrs.onDomain(
        { completed: tap('cdrs.onDomain', 'completed'), updated: tap('cdrs.onDomain', 'updated') },
        watch('cdrs.onDomain'),
      ),
  },
  {
    key: 'notifications.onNotification',
    stream: 'notifications.onNotification',
    open: (s) =>
      s.notifications.onNotification(tap('notifications.onNotification', 'notification'), watch('notifications.onNotification')),
  },
  {
    key: 'softphone.onCallStarted',
    stream: 'softphone.onCallStarted',
    open: (s) => s.softphone.onCallStarted(tap('softphone.onCallStarted', 'event'), watch('softphone.onCallStarted')),
  },
  {
    key: 'softphone.onCallAnswered',
    stream: 'softphone.onCallAnswered',
    open: (s) => s.softphone.onCallAnswered(tap('softphone.onCallAnswered', 'event'), watch('softphone.onCallAnswered')),
  },
  {
    key: 'softphone.onCallEnded',
    stream: 'softphone.onCallEnded',
    open: (s) => s.softphone.onCallEnded(tap('softphone.onCallEnded', 'event'), watch('softphone.onCallEnded')),
  },
  {
    key: 'softphone.onCallMissed',
    stream: 'softphone.onCallMissed',
    open: (s) => s.softphone.onCallMissed(tap('softphone.onCallMissed', 'event'), watch('softphone.onCallMissed')),
  },
];

export const RETAINED_STREAMS = RETAINED.map((r) => r.stream);

/** Open every session-long feed. Returns the teardown. */
export function startCollectors(next: RemoteAppSDK): () => void {
  sdk = next;
  const subs: Subscription[] = [];
  for (const r of RETAINED) {
    try {
      const sub = next.streams.retain(r.key, r.open);
      setStatus(r.stream, sub.status);
      subs.push(sub);
    } catch (e) {
      record('status', r.stream, 'error', { message: String(e) });
    }
  }
  record('mark', 'inspector', 'collectors started', { streams: RETAINED.length });
  return () => {
    for (const s of subs) {
      try {
        s.unsubscribe();
      } catch {
        /* best effort */
      }
    }
    if (sdk === next) sdk = null;
  };
}

// --- feeds that take an argument, opened from the page -----------------------------

export type TargetKind =
  | 'calls.onExtension'
  | 'queues.onQueue'
  | 'agents.onAgent'
  | 'contacts.onUser'
  | 'subscribers.onUser'
  | 'cdrs.onUser';

export const TARGET_KINDS: Array<{ kind: TargetKind; hint: string }> = [
  { kind: 'calls.onExtension', hint: 'extension, e.g. 101' },
  { kind: 'queues.onQueue', hint: 'queue, e.g. 6000' },
  { kind: 'agents.onAgent', hint: 'agent device, user@domain' },
  { kind: 'contacts.onUser', hint: 'user, e.g. 101' },
  { kind: 'subscribers.onUser', hint: 'user, e.g. 101' },
  { kind: 'cdrs.onUser', hint: 'user, e.g. 101' },
];

/** Open one targeted feed; `name` is how it appears in the log. */
export function openTarget(kind: TargetKind, arg: string): { name: string; sub: Subscription } | null {
  const s = sdk?.streams;
  if (!s) return null;
  const name = `${kind}(${arg})`;
  const w = watch(name);
  let sub: Subscription;
  switch (kind) {
    case 'calls.onExtension':
      sub = s.calls.onExtension(arg, { updated: tap(name, 'updated'), ended: tap(name, 'ended') }, w);
      break;
    case 'queues.onQueue':
      sub = s.queues.onQueue(
        arg,
        {
          stats: tap(name, 'stats'),
          waiting: tap(name, 'waiting'),
          left: tap(name, 'left'),
          callUpdated: tap(name, 'callUpdated'),
          callEnded: tap(name, 'callEnded'),
          agentUpdated: tap(name, 'agentUpdated'),
          agentAdded: tap(name, 'agentAdded'),
          agentRemoved: tap(name, 'agentRemoved'),
        },
        w,
      );
      break;
    case 'agents.onAgent':
      sub = s.agents.onAgent(arg, { updated: tap(name, 'updated'), added: tap(name, 'added'), removed: tap(name, 'removed') }, w);
      break;
    case 'contacts.onUser':
      sub = s.contacts.onUser(arg, tap(name, 'contact'), w);
      break;
    case 'subscribers.onUser':
      sub = s.subscribers.onUser(arg, tap(name, 'update'), w);
      break;
    case 'cdrs.onUser':
      sub = s.cdrs.onUser(arg, { completed: tap(name, 'completed'), updated: tap(name, 'updated') }, w);
      break;
  }
  setStatus(name, sub.status);
  return { name, sub };
}

// --- REST snapshots ---------------------------------------------------------------

/**
 * The reads the switchboard's board is built on, logged beside the stream
 * events so the two shapes can be lined up record by record.
 */
export const SNAPSHOT_PATHS = (domain: string): string[] => {
  const d = encodeURIComponent(domain);
  return [`/domains/${d}/calls`, `/domains/${d}/callqueues`, `/domains/${d}/agents`];
};

export async function snapshotRest(api: FlowApiClient, domain: string, paths = SNAPSHOT_PATHS(domain)): Promise<void> {
  await Promise.all(
    paths.map(async (p) => {
      try {
        record('rest', 'rest', p, await api.get(p, { limit: 500 }));
      } catch (e) {
        record('rest', 'rest', p, { error: e instanceof Error ? e.message : String(e) });
      }
    }),
  );
}

// --- summaries and export ---------------------------------------------------------

export interface Count {
  stream: string;
  event: string;
  n: number;
  last: number;
}

export function countEvents(list: readonly Entry[]): Count[] {
  const m = new Map<string, Count>();
  for (const e of list) {
    if (e.kind !== 'event') continue;
    const k = `${e.stream}\u0000${e.event}`;
    const c = m.get(k) ?? { stream: e.stream, event: e.event, n: 0, last: 0 };
    c.n += 1;
    c.last = e.t;
    m.set(k, c);
  }
  return Array.from(m.values()).sort((a, b) => a.stream.localeCompare(b.stream) || a.event.localeCompare(b.event));
}

/** Field -> the value types seen and one example, per stream event. */
export type Shape = Record<string, { types: string[]; example: unknown; seen: number }>;

function typeOf(v: unknown): string {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  return typeof v;
}

function walk(v: unknown, prefix: string, out: Shape, depth: number): void {
  if (depth > 3 || typeOf(v) !== 'object') return;
  for (const [k, child] of Object.entries(v as Record<string, unknown>)) {
    const path = prefix ? `${prefix}.${k}` : k;
    const f = (out[path] ??= { types: [], example: undefined, seen: 0 });
    const t = typeOf(child);
    if (!f.types.includes(t)) f.types.push(t);
    if (f.example === undefined || f.example === null || f.example === '') {
      if (t !== 'object') f.example = child;
    }
    f.seen += 1;
    walk(child, path, out, depth + 1);
  }
}

export function shapes(list: readonly Entry[]): Record<string, Shape> {
  const out: Record<string, Shape> = {};
  for (const e of list) {
    if (e.kind !== 'event') continue;
    walk(e.payload, '', (out[`${e.stream} ${e.event}`] ??= {}), 0);
  }
  return out;
}

export function buildExport(meta: Record<string, unknown>): string {
  return JSON.stringify(
    {
      meta: { ...meta, exportedAt: new Date().toISOString(), entries: entries.length, droppedOldest: dropped },
      statuses: Object.fromEntries(statuses),
      counts: countEvents(entries),
      shapes: shapes(entries),
      entries,
    },
    null,
    1,
  );
}
